	public ConsoleCommand(string command, string description, ConsoleEventFailable action, bool isCheat = false, bool isNetwork = false, bool onlyServer = false, bool isSecret = false, bool allowInDevBuild = false, bool hideBehindDevCommands = false, ConsoleOptionsFetcher optionsFetcher = null, bool alwaysRefreshTabOptions = false, bool remoteCommand = false, bool onlyAdmin = false)
	{
		commands[command.ToLower()] = this;
		Command = command;
		Description = description;
		actionFailable = action;
		IsCheat = isCheat;
		OnlyServer = onlyServer || onlyAdmin;
		IsSecret = isSecret;
		IsNetwork = isNetwork;
		AllowInDevBuild = allowInDevBuild;
		m_tabOptionsFetcher = optionsFetcher;
		m_alwaysRefreshTabOptions = alwaysRefreshTabOptions;
		RemoteCommand = remoteCommand;
		HideBehindDevCommands = hideBehindDevCommands;
		OnlyAdmin = onlyAdmin;
	}

	public ConsoleCommand(string command, string description, ConsoleEvent action, bool isCheat = false, bool isNetwork = false, bool onlyServer = false, bool isSecret = false, bool allowInDevBuild = false, bool hideBehindDevCommands = false, ConsoleOptionsFetcher optionsFetcher = null, bool alwaysRefreshTabOptions = false, bool remoteCommand = false, bool onlyAdmin = false)
	{
		commands[command.ToLower()] = this;
		Command = command;
		Description = description;
		this.action = action;
		IsCheat = isCheat;
		OnlyServer = onlyServer;
		IsSecret = isSecret;
		IsNetwork = isNetwork;
		AllowInDevBuild = allowInDevBuild;
		m_tabOptionsFetcher = optionsFetcher;
		m_alwaysRefreshTabOptions = alwaysRefreshTabOptions;
		RemoteCommand = remoteCommand;
		HideBehindDevCommands = hideBehindDevCommands;
		OnlyAdmin = onlyAdmin;
	}

	public List<string> GetTabOptions()
	{
		if (m_tabOptionsFetcher != null && (m_tabOptions == null || m_alwaysRefreshTabOptions))
		{
			m_tabOptions = m_tabOptionsFetcher();
		}
		return m_tabOptions;
	}

	public void RunAction(ConsoleEventArgs args)
	{
		//IL_0056: Unknown result type (might be due to invalid IL or missing references)
		//IL_005b: Unknown result type (might be due to invalid IL or missing references)
		//IL_00d5: Unknown result type (might be due to invalid IL or missing references)
		//IL_00dc: Expected I4, but got Unknown
		if (IsCheat && !Achievements.IsCheatedAtAll() && args[0].ToLower() != "confirmcheats")
		{
			args.Context.AddString(Localization.instance.Localize("$achievements_confirm_cheat"));
			return;
		}
		if (args.Length >= 2)
		{
			List<string> tabOptions = GetTabOptions();
			if (tabOptions != null)
			{
				Enumerator<string> enumerator = tabOptions.GetEnumerator();
				try
				{
					while (enumerator.MoveNext())
					{
						string current = enumerator.Current;
						if (current != null && args[1].ToLower() == current.ToLower())
						{
							args.Args[1] = current;
							break;
						}
					}
				}
				finally
				{
					((IDisposable)enumerator).Dispose();
				}
			}
		}
		if (action != null)
		{
			action(args);
		}
		else
		{
			object obj = actionFailable(args);
			if (obj is Boolean && (int)(Boolean)obj == 0)
			{
				args.Context.AddString(String.Concat((string[])(object)new String[5] { "<color=#8b0000>Error executing command. Check parameters and context.</color>\n   <color=#888888>", Command, " - ", Description, "</color>" }));
			}
			string text = (string)((obj is String) ? obj : null);
			if (text != null)
			{
				args.Context.AddString(String.Concat((string[])(object)new String[7] { "<color=#8b0000>Error executing command: ", text, "</color>\n   <color=#888888>", Command, " - ", Description, "</color>" }));
			}
		}
		if ((bool)Game.instance)
		{
			PlayerProfile playerProfile = Game.instance.GetPlayerProfile();
			if (IsCheat)
			{
				playerProfile.m_usedCheats = true;
				playerProfile.IncrementStat(PlayerStatType.Cheats);
			}
			Utils.IncrementOrSet<string>(playerProfile.m_playerStats[1].m_knownCommands, args[0].ToLower(), 1f);
			Utils.IncrementOrSet<string>(playerProfile.m_playerStats[Achievements.GetCurrentAchievementDifficultyIndex()].m_knownCommands, args[0].ToLower(), 1f);
		}
	}

	public bool ShowCommand(Terminal context)
	{
		if (!IsSecret && (IsValid(context) || ((bool)ZNet.instance && !ZNet.instance.IsServer() && RemoteCommand)))
		{
			if (!m_cheat)
			{
				return !HideBehindDevCommands;
			}
			return true;
		}
		return false;
	}

	public bool IsValid(Terminal context, bool skipAllowedCheck = false)
	{
		if ((!IsCheat || context.IsCheatsEnabled()) && (context.isAllowedCommand(this) || skipAllowedCheck) && (!IsNetwork || (bool)ZNet.instance))
		{
			if (OnlyServer)
			{
				if ((bool)ZNet.instance)
				{
					return ZNet.instance.IsServer();
				}
				return false;
			}
			return true;
		}
		return false;
	}
}

