using System.Collections.Generic;
using System.Reflection;
using BepInEx;
using HarmonyLib;
using Splatform;

namespace NxeonDevAdmin
{
    /// <summary>
    /// Lets a player who is listed in a dedicated server's adminlist.txt use
    /// cheat ("devcommands") console commands such as god, fly, debugmode,
    /// ghost and spawn while connected to that server.
    ///
    /// THIS IS A CLIENT-SIDE PLUGIN. It has to be installed in the PLAYER'S
    /// OWN BepInEx (r2modman/Thunderstore profile -> BepInEx/plugins). It does
    /// nothing useful on the dedicated server. Version 1.0.0 was shipped ONLY
    /// to servers and could not work. See README.md and
    /// docs/DOCUMENTATION.md, "Valheim dev commands: how it really works
    /// (2026-10-01)", for the decompiled evidence.
    ///
    /// Why it has to run on the client (Valheim l-1.0.16, network version 40,
    /// assembly_valheim.dll sha256 50035055...e39fd):
    ///
    ///   Terminal.IsCheatsEnabled() => m_cheat && ZNet.instance && ZNet.instance.IsServer()
    ///   ConsoleCommand.IsValid(ctx) => (!IsCheat || ctx.IsCheatsEnabled()) && ...
    ///                                  && (!OnlyServer || ZNet.instance.IsServer())
    ///
    /// Commands such as god, fly and debugmode run in the CLIENT's own
    /// Terminal and are checked against the CLIENT's own state. On a client
    /// connected to a dedicated server IsServer() is false, so both checks fail
    /// and Terminal.TryRunCommand prints "'god' is not valid in the current
    /// context." Those commands are not forwarded to the server. Only commands
    /// built with remoteCommand: true are forwarded, and god, fly and debugmode
    /// are not built that way. A server-side patch is never consulted for them.
    ///
    /// What this plugin changes, and only while the local player is a
    /// recognized admin of the server they are connected to (the server
    /// sends its adminlist to every client through the "AdminList" RPC):
    ///   1. IsCheatsEnabled() also returns true when m_cheat is set (the player
    ///      typed `devcommands`).
    ///   2. ConsoleCommand.IsValid() lets the remaining OnlyServer commands
    ///      (fly, debugmode, nocost, exploremap ...) run locally. Commands
    ///      flagged RemoteCommand (sleep, skiptime, setkey ...) are left alone,
    ///      so they are still forwarded to the server the vanilla way.
    ///   3. Sets Game.isModded = true. Iron Gate asks every mod to do this. It
    ///      also means cheat commands skip the "confirmcheats" prompt (vanilla
    ///      Achievements.IsCheatedAtAll() includes Game.isModded).
    ///
    /// On the dedicated server both patches do nothing (IsServer() is true, so
    /// vanilla already returns the answer). That is why the same DLL can stay
    /// bind-mounted there.
    /// </summary>
    [BepInPlugin(PluginGuid, PluginName, PluginVersion)]
    public class Plugin : BaseUnityPlugin
    {
        public const string PluginGuid = "cloud.nxeon.devadmin";
        public const string PluginName = "Nxeon Dev Admin";
        public const string PluginVersion = "2.0.0";

        private void Awake()
        {
            Game.isModded = true;
            new Harmony(PluginGuid).PatchAll(typeof(Plugin).Assembly);
            Logger.LogInfo($"{PluginName} {PluginVersion} loaded. Client side: if you are on a server's adminlist, type 'devcommands' in the F5 console to unlock god/fly/debugmode on that server.");
        }
    }

    internal static class AdminCheck
    {
        /// <summary>
        /// True only on a CLIENT (not the server or a listen host) whose local
        /// user appears in the admin list the server synced to it.
        ///
        /// Vanilla ZNet.LocalPlayerIsAdminOrHost() on a client does
        /// adminList.Contains(localUserId.ToString()), which is the PREFIXED
        /// form "Steam_7656...". The server's own check (ZNet.ListContainsId)
        /// also accepts the bare SteamID64, and adminlist.txt files written
        /// from the lloesche image's ADMINLIST_IDS hold bare IDs. With bare IDs
        /// the vanilla client check is false, so this check accepts the same
        /// forms the server does.
        /// </summary>
        public static bool IsRemoteAdminClient()
        {
            ZNet znet = ZNet.instance;
            if (znet == null || znet.IsServer()) return false;
            if (znet.LocalPlayerIsAdminOrHost()) return true;

            UserInfo local = UserInfo.GetLocalUser();
            if (local == null) return false;
            PlatformUserID id = local.UserId;
            if (!id.IsValid) return false;

            List<string> list = znet.GetAdminList();
            if (list == null || list.Count == 0) return false;

            if (list.Contains(id.ToString())) return true;
            if (id.m_userID != null && list.Contains(id.m_userID)) return true;
            PlatformUserID filtered = PlatformUserID.FilterPlatformUserID(id);
            if (!filtered.Equals(id) && list.Contains(filtered.ToString())) return true;
            return false;
        }
    }

    [HarmonyPatch(typeof(Terminal), nameof(Terminal.IsCheatsEnabled))]
    internal static class Terminal_IsCheatsEnabled_Patch
    {
        private static void Postfix(ref bool __result)
        {
            if (__result) return;
            if (!Terminal.m_cheat) return;
            if (AdminCheck.IsRemoteAdminClient()) __result = true;
        }
    }

    [HarmonyPatch(typeof(Terminal.ConsoleCommand), nameof(Terminal.ConsoleCommand.IsValid))]
    internal static class ConsoleCommand_IsValid_Patch
    {
        // Terminal.isAllowedCommand is protected virtual (Chat overrides it to
        // refuse every cheat command). Invoking through MethodInfo keeps the
        // virtual dispatch, so chat-typed cheats stay refused.
        private static readonly MethodInfo IsAllowedCommand =
            AccessTools.Method(typeof(Terminal), "isAllowedCommand");

        private static void Postfix(Terminal.ConsoleCommand __instance, Terminal context, bool skipAllowedCheck, ref bool __result)
        {
            if (__result) return;
            if (!__instance.OnlyServer) return;      // vanilla refused for a reason other than OnlyServer
            if (__instance.RemoteCommand) return;    // leave it to the vanilla RPC_RemoteCommand forwarding
            if (!Terminal.m_cheat) return;
            if (context == null) return;
            if (!AdminCheck.IsRemoteAdminClient()) return;

            if (__instance.IsCheat && !context.IsCheatsEnabled()) return;
            if (!skipAllowedCheck)
            {
                if (IsAllowedCommand == null) return;
                object allowed = IsAllowedCommand.Invoke(context, new object[] { __instance });
                if (!(allowed is bool b) || !b) return;
            }
            if (__instance.IsNetwork && ZNet.instance == null) return;
            __result = true;
        }
    }
