// Static-dispatch harness: loads the REAL assembly_valheim.dll (l-1.0.16) in a
// plain .NET process, registers the REAL vanilla console commands via
// Terminal.InitTerminal(), and drives the REAL Terminal.TryRunCommand() decision
// logic as a remote client of a dedicated server. Only Unity-native touch
// points are stubbed (UnityEngine.Object bool/== operators, UI output, the
// actual command bodies, the RPC send, the local Steam user lookup).
using System;
using System.Collections.Generic;
using System.Reflection;
using System.Runtime.CompilerServices;
using HarmonyLib;
using Splatform;

static class Log { public static List<string> Lines = new List<string>(); }

static class Stubs
{
    public static PlatformUserID LocalId = new PlatformUserID("Steam", 76561198327183538UL);
    public static bool ObjImplicit(UnityEngine.Object exists, ref bool __result) { __result = !ReferenceEquals(exists, null); return false; }
    public static bool ObjEq(UnityEngine.Object x, UnityEngine.Object y, ref bool __result) { __result = ReferenceEquals(x, y); return false; }
    public static bool ObjNeq(UnityEngine.Object x, UnityEngine.Object y, ref bool __result) { __result = !ReferenceEquals(x, y); return false; }
    public static bool AddString(string text) { Log.Lines.Add("OUT: " + text); return false; }
    public static bool RunAction(Terminal.ConsoleCommand __instance) { Log.Lines.Add("RAN-LOCALLY: " + __instance.Command); return false; }
    public static bool RemoteCommand(string command) { Log.Lines.Add("FORWARDED-TO-SERVER: " + command); return false; }
    public static bool GetLocalUser(ref UserInfo __result)
    {
        var u = (UserInfo)RuntimeHelpers.GetUninitializedObject(typeof(UserInfo));
        typeof(UserInfo).GetField("UserId").SetValue(u, LocalId);
        __result = u; return false;
    }
}

static class Program
{
    static int failures = 0;
    static Terminal console;

    static void Expect(string label, string cmd, string expectPrefix)
    {
        Log.Lines.Clear();
        console.TryRunCommand(cmd);
        string got = string.Join(" | ", Log.Lines);
        bool ok = got.StartsWith(expectPrefix);
        if (!ok) failures++;
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  [{label}] {cmd,-12} -> {got}");
    }

    static void Main(string[] args)
    {
        bool applyPlugin = args.Length > 0 && args[0] == "--with-plugin";
        var h = new Harmony("harness");
        var objT = typeof(UnityEngine.Object);
        h.Patch(AccessTools.Method(objT, "op_Implicit"), prefix: new HarmonyMethod(typeof(Stubs), nameof(Stubs.ObjImplicit)));
        h.Patch(AccessTools.Method(objT, "op_Equality"), prefix: new HarmonyMethod(typeof(Stubs), nameof(Stubs.ObjEq)));
        h.Patch(AccessTools.Method(objT, "op_Inequality"), prefix: new HarmonyMethod(typeof(Stubs), nameof(Stubs.ObjNeq)));
        h.Patch(AccessTools.Method(typeof(Terminal), "AddString", new[] { typeof(string) }), prefix: new HarmonyMethod(typeof(Stubs), nameof(Stubs.AddString)));
        h.Patch(AccessTools.Method(typeof(Terminal.ConsoleCommand), "RunAction"), prefix: new HarmonyMethod(typeof(Stubs), nameof(Stubs.RunAction)));
        h.Patch(AccessTools.Method(typeof(ZNet), "RemoteCommand"), prefix: new HarmonyMethod(typeof(Stubs), nameof(Stubs.RemoteCommand)));
        h.Patch(AccessTools.Method(typeof(UserInfo), "GetLocalUser"), prefix: new HarmonyMethod(typeof(Stubs), nameof(Stubs.GetLocalUser)));

        AccessTools.Method(typeof(Terminal), "InitTerminal").Invoke(null, null);

        // A remote CLIENT of a dedicated server.
        var znet = (ZNet)RuntimeHelpers.GetUninitializedObject(typeof(ZNet));
        AccessTools.Field(typeof(ZNet), "m_instance").SetValue(null, znet);
        AccessTools.Field(typeof(ZNet), "m_isServer").SetValue(null, false);
        string adminForm = Environment.GetEnvironmentVariable("ADMIN_FORM") ?? "bare";
        var admins = new List<string>();
        if (adminForm == "bare") admins.Add("76561198327183538");
        else if (adminForm == "prefixed") admins.Add("Steam_76561198327183538");
        AccessTools.Field(typeof(ZNet), "m_adminListForRpc").SetValue(znet, admins);
        console = (Terminal)RuntimeHelpers.GetUninitializedObject(typeof(global::Console));
        Game.isModded = true;

        if (applyPlugin) new Harmony("cloud.nxeon.devadmin").PatchAll(typeof(NxeonDevAdmin.Plugin).Assembly);

        bool isAdmin = adminForm != "none";
        Console.WriteLine($"mode={(applyPlugin ? "client WITH NxeonDevAdmin 2.0.0" : "vanilla client")} adminlist={adminForm} m_isServer=false");

        // Before devcommands
        Terminal.m_cheat = false;
        Expect("before devcommands", "god", "OUT: 'god' is not valid");
        Terminal.m_cheat = true; // what `devcommands` does locally on the client (it also forwards)
        Console.WriteLine($"      IsCheatsEnabled() after devcommands = {console.IsCheatsEnabled()}");
        bool unlocked = applyPlugin && isAdmin;
        foreach (var c in new[] { "god", "ghost", "fly", "debugmode", "nocost", "spawn Wood", "heal", "exploremap" })
            Expect("after devcommands", c, unlocked ? "RAN-LOCALLY: " : "OUT: '");
        // Commands vanilla forwards to the server must still be forwarded, not run locally.
        foreach (var c in new[] { "sleep", "skiptime 600", "listkeys" })
            Expect("remote cmd", c, "FORWARDED-TO-SERVER: ");
        // devcommands itself is always valid locally (and forwards from inside its own action).
        Expect("devcommands", "devcommands", "RAN-LOCALLY: devcommands");

