import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";

// Static checks on the committed NxeonDevAdmin plugin (worker/assets/valheim/NxeonDevAdmin.dll)
// and its source. The behavioural proof (the real Valheim dispatch code with and without the
// plugin) is tools/valheim-plugins/NxeonDevAdmin.Harness/run.sh. It needs the game DLLs, so it
// is not part of `npm test`.
const root = join(__dirname, "..");
const dll = readFileSync(join(root, "worker/assets/valheim/NxeonDevAdmin.dll"));
const src = readFileSync(join(root, "tools/valheim-plugins/NxeonDevAdmin/Plugin.cs"), "utf8");

// #Strings heap (type/member names) is UTF-8. #US heap (string literals) is UTF-16LE.
const hasName = (s: string) => dll.includes(Buffer.from(`\0${s}\0`, "utf8"));
const hasLiteral = (s: string) => dll.includes(Buffer.from(s, "utf16le"));

test("DLL is a .NET assembly built from this source version", () => {
  assert.equal(dll.subarray(0, 2).toString("latin1"), "MZ");
  assert.ok(hasName("NxeonDevAdmin"), "assembly name");
  const version = /PluginVersion = "([^"]+)"/.exec(src)?.[1];
  assert.equal(version, "2.0.0");
  assert.ok(hasLiteral(version!), "DLL carries the same PluginVersion literal as Plugin.cs");
  assert.ok(hasLiteral("cloud.nxeon.devadmin"), "plugin GUID");
});

test("DLL patches both client-side gates, not just IsCheatsEnabled", () => {
  // Patch targets as Harmony sees them (nameof() compiles to these literals).
  assert.ok(hasLiteral("IsCheatsEnabled"), "Terminal.IsCheatsEnabled patch target");
  assert.ok(hasLiteral("IsValid"), "Terminal.ConsoleCommand.IsValid patch target");
  assert.ok(hasName("Terminal_IsCheatsEnabled_Patch"));
  assert.ok(hasName("ConsoleCommand_IsValid_Patch"));
  // Vanilla Chat.isAllowedCommand still has to be consulted (chat must not run cheats).
  assert.ok(hasLiteral("isAllowedCommand"));
  // Tolerant admin check (bare SteamID64 or Steam_ prefixed), via Splatform.
  assert.ok(hasName("GetAdminList"));
  assert.ok(hasName("FilterPlatformUserID"));
  assert.ok(hasName("Splatform"));
  // Sets the modded flag Iron Gate asks mods to set.
  assert.ok(hasName("isModded"));
});

test("source never unlocks commands that vanilla forwards to the server", () => {
  assert.match(src, /if \(__instance\.RemoteCommand\) return;/);
  assert.match(src, /znet == null \|\| znet\.IsServer\(\)\) return false;/);
});

